/* Build stamp.  Generated by mbt at every build: MBT_VERSION from the project
** version, MBT_COMMIT from `git rev-parse --short HEAD` (with "-dirty"
** appended when a TRACKED file differs from HEAD, and "unknown" outside a git
** checkout), MBT_COMMIT_DIRTY as the matching 0/1 flag.  Included here rather
** than in httpd.h so a new commit restamps the banner without rebuilding every
** object (mbt#59). */
#include <buildstamp.h>

#include "httpd.h"
#include "httpdmsg.h"               /* operator message catalog         */
#include "httpracf.h"               /* HTTP_RACF_NOTPROT (res_probe)    */
#include "clibgrt.h"
#include "clibsock.h"
#include "clibver.h"                /* libc370_version()                */
#include "clibauth.h"               /* __autask/__austep/__uatask/__uastep */

static int socket_thread(void *arg1, void *arg2);
static int worker_thread(void *udata, CTHDWORK *work);

unsigned __stklen = 64*1024;

int main(int argc, char **argv);

