/* The security environment the STC started under -- the STC/STCGROUP account
** RAKF hands out -- is retained by stc_identity() rather than released, so
** that shutdown can put it back before it gives APF authorization up.  It
** lives in the HTTPD control block as httpd->stc_prev_acee: NULL until the
** switch succeeds, which is what makes the restore a no-op on every path that
** never got that far.
**
** It was a file-scope static here until #197.  That is module storage, and a
** module fetched from an APF-authorized or LNKLST library lands in key-0
** storage, so the key-8 store in stc_identity_restore() -- the one outside the
** __super() window -- abended S0C4 on every P HTTPD.  main() memsets the block
** before any path can reach the restore, so the NULL it relies on is
** established exactly as reliably as the static's initializer was. */

/* Replace the default STC security environment with a dedicated, low
** privilege identity.  Called once, from initialize(), before anything opens
** a data set.  See the block comment at the call site for why this exists.
**
** The new ACEE is deliberately not freed: it becomes the address space's
** resting identity for the life of the server, and RTM releases it with the
** address space. */
static void
stc_identity(HTTPD *httpd, const char *user, const char *group)
{
	unsigned char	savekey;
	ACEE			*old_acee;
	ACEE			*new_acee;
	int				racf_rc	= 0;

	if (__super(PSWKEY0, &savekey)) {
		wtof(MSG_STCID_NOKEY);
		return;
	}

	/* The inherited environment is RETAINED, not released.
	**
	** Releasing it would be tidier but breaks shutdown.  HTTPD uses SVC 244 to
	** acquire APF authorization at start and to release it at end (__uatask()).
	** The acquire runs before this function -- RACINIT needs key 0, which needs
	** APF, so that order is forced -- and is covered by the STC account.  The
	** release at P HTTPD would run as the new identity, which has no
	** FACILITY SVC244 profile, and RAKF logs RAKF0005/RAKF000A on every single
	** stop.  stc_identity_restore() puts this ACEE back first, so the SVC 244
	** at the end runs under the same account that took the authorization out.
	**
	** Order also matters within this function, and the obvious order is wrong.
	** Releasing the inherited environment FIRST would leave nothing to fall
	** back on when the logon fails: racf_logout() does not merely free the
	** block, it __cas()es ASXBSENV to zero when the field still points at what
	** it deleted (libc370 raclgout.c does it by hand because RAKF leaves the
	** dead pointer).  A failed logon would then leave the address space with NO
	** resting identity at all -- not what HTTPD004W promises, and worse than the
	** privileged identity #177 set out to replace.  So: log on, then install. */
	old_acee = racf_get_acee();

	new_acee = racf_login(user, NULL, group, &racf_rc);
	if (new_acee) {
		racf_set_acee(new_acee);
		httpd->stc_prev_acee = old_acee;    /* for stc_identity_restore() */
		wtof(MSG_STCID_SET, user, group);
	}
	else {
		wtof(MSG_STCID_FAILED, user, group, racf_rc);
	}

	__prob(savekey, NULL);
}

/* Put the STC account back, immediately before APF authorization is released.
**
** __uatask() issues SVC 244, which RAKF gates on FACILITY SVC244.  The task
** took the authorization out under the STC account and must give it back under
** the same one, or every P HTTPD ends with RAKF0005/RAKF000A -- harmless, since
** the address space is ending anyway, but a permission failure logged on the
** healthy path teaches operators to ignore RAKF messages.
**
** Note this deliberately overwrites whatever ASXBSENV happens to hold, which by
** shutdown is often a CLIENT's ACEE rather than HTTPD/USER (measured: RAKF's
** RACINIT ENVIR=CREATE appears to plant the ACEE it creates, so every logon
** displaces the server identity -- see issue #176).  Restoring unconditionally
** is right precisely because the field cannot be trusted to still hold ours.
**
** racf_set_acee() does its own supervisor/key switching, so no __super() here.
** It does need APF, which is why this runs BEFORE the release, not after.
**
** The saved ACEE lives in the HTTPD control block rather than in a module
** static (#197): main()'s HTTPD is automatic storage and therefore key 8, so
** the clearing store below is legal whatever key the module itself is in. */
static void
stc_identity_restore(HTTPD *httpd)
{
	if (!httpd->stc_prev_acee) return;

	racf_set_acee(httpd->stc_prev_acee);
	httpd->stc_prev_acee = NULL;
}

/* res_probe() - say once, at start, that a RES= route names a resource no
** profile covers.
**
** Stage 2 of auth_gate() permits every request to such a route: SAF answers
** rc 4 ("resource not protected"), httpracf() counts that as allowed, and
** #136 settled deliberately on keeping it that way.  But rc 4 is also exactly
** what a typo in the class or in the resource name looks like, and the one
** keyword whose whole job is authorization should not fail quietly in the
** permissive direction (#137).  The decision itself is unchanged here -- this
** only makes the misconfiguration visible while it can still be fixed.
**
** DEBUG 1 already traces the same condition (httpxauth.c), but per request and
** only for someone who knew to look.  This line is unconditional and lands in
** the job log and the Master Trace Table.
**
** The probe runs under the server's own resting identity -- HTTPD/USER after
** stc_identity(), since acee == NULL takes RACHECK's ASXBSENV fallback -- and
** not under a client's.  That is enough because it asks only whether a profile
** EXISTS: measured against RAKF, an uncovered resource answers 4 whoever asks,
** and the identity moves the answer only between 0 and 8, both of which mean a
** profile is there.
**
** All three arms were measured in one start on mvsdev, with the server running
** as HTTPD/USER: FACILITY:HTTPD.NOSUCH (no profile at all) warned, while
** FACILITY:LIBC370.TSTRACMX.ALLOW (group USER holds READ, so rc 0) and
** FACILITY:LIBC370.TSTRACMX.DENY (defined, nobody permitted, so rc 8) both
** stayed silent.  The second of those is the one worth keeping: it is what
** shows a REFUSAL is not mistaken for a missing profile, which is the whole
** claim this function rests on.  Both profiles exist on that system as RACHECK
** fixtures for libc370's tstracmx, listed in SYS1.SECURE.CNTL(PROFILES).
**
** That is a RAKF property and not a SAF one: under RACF
** with PROTECTALL the same resource answers 8 for an ordinary user and 0 for a
** SPECIAL one (see the RACHECK return codes in libc370 racauth.c), and MVS
** 3.8j with no security product at all answers 0.  Only rc 4 warns, so on
** either of those this stays silent rather than warning falsely.
**
** AUTH=NONE routes are skipped: auth_gate() never reaches stage 2 for them and
** HTTPD414W has already said the RES= is ignored.  parse_kv_tail() leaves
** resclass set on such a route rather than clearing it, so this test is live
** code, not a defensive one.
**
** Cost is one RACHECK per RES= route, once -- and it audits nothing, now that
** libc370#63 has racf_auth() setting LOG=NONE instead of DSTYPE=V.
*/
static void
res_probe(HTTPD *httpd)
{
	unsigned	count;
	unsigned	n;

	if (!httpd->route) return;

	count = array_count(&httpd->route);
	for (n = 0; n < count; n++) {
		HTTPROUTE *route = httpd->route[n];

		if (!route->resclass || !route->resname) continue;
		if (route->auth == HTTP_AUTH_NONE) continue;

		if (racf_auth(NULL, route->resclass, route->resname, route->resattr)
		    == HTTP_RACF_NOTPROT) {
			wtof(MSG_RES_NO_PROFILE,
			     route->resclass, route->resname, route->path);
		}
	}
}

/* initialize() - returns the step return code: 0 when the server came up, 8
** when it refused to.  It used to be void, which is how a Parmlib error the
** server explicitly refuses to start on still ended the step CC 0000 (#226):
** http_config() returned 8, initialize() acted on it, and the value had
** nowhere to go.  main() then inferred the failure from !httpd->listen, and an
** inference carries no severity -- so in JES a refused configuration was
** indistinguishable from a clean P HTTPD, for $DJ, for an automation rule
** keyed on COND CODE, and for anything that restarts a failed STC.
**
** Kept in its own variable rather than reusing rc, which is written again
** further down by cthread_post() and cred_init(); returning rc would report
** whichever of those ran last. */
static int
initialize(int argc, char **argv)
{
    int                 initrc  = 0;    /* step return code -- see above */
    CLIBGRT             *grt        = __grtget();
    CLIBPPA             *ppa        = __ppaget();
    HTTPD               *httpd      = grt->grtapp1;
    unsigned            *psa        = (unsigned *)0;
    unsigned            *ascb       = (unsigned *)psa[0x224/4]; /* PSAAOLD  */
    unsigned            asid        = ((ascb[0x24/4]) >> 16);   /* ASCBASID */
    int                 rc;
    int					i;
    CTHDTASK            *task;
    const char 			*config		= NULL;
    const char			*stcuser	= HTTPD_STC_USER;
    const char			*stcgroup	= HTTPD_STC_GROUP;

    /* if something goes all wrong, capture it! */
    abendrpt(ESTAE_CREATE, DUMP_DEFAULT);

	/* look for "CONFIG=", "STCUSER=" and "STCGROUP=" parms.
	**
	** The identity keywords are read from the JCL PARM rather than from the
	** Parmlib on purpose: the logon below has to happen BEFORE http_config(),
	** which opens the Parmlib member and initializes UFS, and those are
	** exactly the file accesses that should no longer run under STC/STCGROUP.
	** Reading them from the member being opened would be circular. */
	for(i=0; i < argc; i++) {
		if (memcmp(argv[i], "CONFIG=", 7)==0) {
			config = &argv[i][7];
			while(*config=='=' || isspace((unsigned char)*config)) config++;
			if (!*config) config = "CONFIG";
		}
		else if (memcmp(argv[i], "STCUSER=", 8)==0) {
			stcuser = &argv[i][8];
			while(*stcuser=='=' || isspace((unsigned char)*stcuser)) stcuser++;
			if (!*stcuser) stcuser = HTTPD_STC_USER;
		}
		else if (memcmp(argv[i], "STCGROUP=", 9)==0) {
			stcgroup = &argv[i][9];
			while(*stcgroup=='=' || isspace((unsigned char)*stcgroup)) stcgroup++;
			if (!*stcgroup) stcgroup = HTTPD_STC_GROUP;
		}
	}

	/* STC identity switch: RACINIT ENVIR=CREATE for the configured userid.
	**
	** RAKF has no started-procedures table: its RACINIT path uses the started
	** procedure name only to decide THAT the caller is an STC, never WHICH
	** one, and assigns one hardcoded account -- STC/STCGROUP.  On a stock RAKF
	** profile set STCGROUP holds ALTER on every data set on the system, so the
	** server's resting identity, the one every RACF decision falls back to when
	** the caller passes no ACEE, is the most privileged one there is.  Any CGI
	** that does not establish an ACEE of its own inherits it (issue #177).
	**
	** racf_login() with pass == NULL bypasses password checking, so nothing has
	** to be stored anywhere; the STC is already APF authorized by this point.
	**
	** A failure warns and continues rather than refusing to start: #177 left
	** the policy open, and refusing turns a profile typo into an outage, while
	** continuing only leaves the identity where it already was.  Both paths say
	** so loudly -- what must not happen is a silent fallback. */
	stc_identity(httpd, stcuser, stcgroup);

    /* The block itself was zeroed by main() before any of this ran -- it has
       to be, because stc_identity() above already stores into it and because
       the early-failure paths in main() reach stc_identity_restore() without
       ever calling us (#197). */
    strcpy(httpd->eye, HTTPD_EYE);
    httpd->flag |= HTTPD_FLAG_INIT;
    sprintf(httpd->rname, "HTTPD.%04X", asid);

    /* lock the httpd while we're making changes and creating threads */
    lock(httpd,0);

    /* httpd <--> httpx */
    httpd->httpx = httpx;
    
    /* set the server up time */
    httpd->uptime = time64(NULL);

    /* Server version.  MBT_VERSION rather than a -DVERSION on the command
       line: as a header it is a real prerequisite via -MMD, so a version or
       commit change recompiles this TU instead of leaving it stamped with the
       previous value.  Kept in its original case -- it is a value, and the
       WTO paths upper case their own copy (httpdmsg.h rule 3). */
    httpd->version	= MBT_VERSION;

	/* Get configuration from member/dataset/NULL */
	rc = http_config(httpd, config);
	if (rc) {
		/* The member is named by HTTPD022I above, and the specific failure by
		   the message right before this one -- printing the CONFIG= parm here
		   only ever produced "(null)", since it is not what gets read (#166). */
		wtof(MSG_CFG_ERRORS);
		if (httpd->listen) {
			closesocket(httpd->listen);
			httpd->listen = 0;
		}
		initrc = rc;                    /* 8 from http_config() (#226) */
		goto quit;
	}

	/* SMF configured but inactive is worth a line unasked: records are being
	** produced for a writer that is not there.  The healthy case is not --
	** it is one of the values F HTTPD,D CONFIG reports on demand (#184). */
	if (httpd->smf_level > SMF_LEVEL_NONE && !smf_active()) {
		wtof(MSG_SMF_INACTIVE, (int)httpd->smf_type);
	}

	/* Same shape, same reason: a RES= route whose resource has no profile is
	** configured for an authorization that cannot happen.  The routes exist
	** only once http_config() has parsed them, and there is no way to reload
	** the Parmlib, so this is the one point that needs it (#137). */
	res_probe(httpd);

    /* create socket thread */
    httpd->socket_thread = cthread_create_ex(socket_thread,
        httpd, httpx, 32*1024);
    if (!httpd->socket_thread) {
        wtof(MSG_NO_SOCKET_THREAD);
        closesocket(httpd->listen);
        httpd->listen = 0;
        initrc = 8;                     /* did not come up either (#226) */
        goto quit;
    }

    httpd->flag |= HTTPD_FLAG_LISTENER;

    /* update the main() thread information */
    task = cthread_self();
    if (task) {
        httpd->self = task;
        task->func = main;
        task->arg1 = (void*)argc;
        task->arg2 = argv;
        task->stacksize = ppa->ppastkln;
    }

	/* check configuration max and min task values */
    if (!(httpd->cfg_maxtask)) httpd->cfg_maxtask = 9;
    if (!(httpd->cfg_mintask)) httpd->cfg_mintask = 3;
    if (httpd->cfg_mintask > httpd->cfg_maxtask) {
		httpd->cfg_maxtask = httpd->cfg_mintask;
	}

    /* create 1 dispatcher and max 9 worker threads (576K total storage stack) */
    /* Note: the thread manager will only start 3 threads initially */
    httpd->mgr = cthread_manager_init(httpd->cfg_maxtask, worker_thread, httpd, 64*1024);
    if (!httpd->mgr) {
        /* gripe and continue -- deliberately does NOT set initrc.  Whether a
           server with no worker pool should start at all is a separate
           question from what code it ends with, and this path has always
           chosen to come up; #226 only made the refusals honest. */
        wtof(MSG_NO_WORKERS);
    }

	/* set the min task for the thread manager */
    if (httpd->mgr) {
		CTHDMGR *mgr = httpd->mgr;

        lock(mgr,1);

		mgr->mintask = httpd->cfg_mintask;
		if (httpd->cfg_mintask > mgr->maxtask) mgr->maxtask = httpd->cfg_mintask;

		/* wake up the thread manager thread */
		rc = cthread_post(&mgr->wait, CTHDMGR_POST_DATA);

        unlock(mgr,1);
    }
    
    /* Initialize CGI context pointers array */
    i = (httpd->cfg_cgictx + 1) * sizeof(void *);
    httpd->cgictx = (void **) calloc(1, (size_t)i);

quit:
	/* Initialize our credential key.

	   The salt used to be the HTTPD block on its own.  That is not a secret:
	   of its 392 bytes roughly half are literal text (eye catcher, docroot,
	   codepage), the rest is Parmlib configuration plus counters that are all
	   zero at this point, and the only varying part is a handful of GETMAIN
	   addresses.  MVS 3.8j has no address space layout randomisation, so for
	   the same load module, region size and Parmlib those addresses reproduce
	   and the key came out identical on every start -- derivable by anyone
	   holding the load module and the Parmlib (#188).

	   Mixing STCK and this address space's own control block addresses through
	   SHA-256 makes the key differ per start.  That matters twice: the CREDID
	   passwords encrypted with it stop being decryptable from a dump by someone
	   who can rebuild the server, and the key becomes usable as the secret that
	   makes credtok_rand()'s output unpredictable.

	   Note this invalidates any credential built by a previous instance: the
	   encrypted CREDID is the lookup key in cred_find_by_id() and it is
	   ciphertext.  Harmless, because the store dies with the address space --
	   but it would matter if credentials were ever persisted. */
	{
		SHA256_CTX          ctx;
		unsigned char       salt[32];
		unsigned long long  tod;
		unsigned            *tcb  = (unsigned *)psa[0x21C/4];  /* PSATOLD */
		void                *self = httpd;

		__asm__("STCK\t0(%0)" : : "r" (&tod));

		sha256_init(&ctx);
		sha256_update(&ctx, (unsigned char *)&tod,  sizeof(tod));
		sha256_update(&ctx, (unsigned char *)httpd, sizeof(HTTPD));
		sha256_update(&ctx, (unsigned char *)&self, sizeof(self));
		sha256_update(&ctx, (unsigned char *)&ascb, sizeof(ascb));
		sha256_update(&ctx, (unsigned char *)&tcb,  sizeof(tcb));
		sha256_final(&ctx, salt);

		rc = cred_init(salt, sizeof(salt));

		memset(salt, 0, sizeof(salt));
	}
	/* Same classification as the worker pool above: HTTPD047E says logins are
	   dead, but the server has always come up anyway, so this does not set
	   initrc either.  Note rc is cred_init()'s from here on -- initrc is what
	   this function returns. */
	if (rc) {
		wtof(MSG_CREDKEY_FAILED, rc);
	}

	/* Cache the blowfish key pointer in the HTTPD block so CGI-context code
	   (http_get_password) can reach it without credkey()/__wsaget(), which
	   only read the key from httpd's own GRT.  cred_init() runs here in that
	   GRT, so credkey() is valid; the key bytes live at a stable WSA address
	   readable across the shared address space, so caching the pointer (no
	   copy) is enough for a CGI running under its own GRT (issue #111). */
	httpd->credkey = credkey();

	/* Likewise cache the credential array pointer so http_logout() can reach
	   httpd's real store from a CGI's GRT.  cred_array() is GRT-relative too,
	   so a CGI calling it sees an empty/foreign array and logout invalidates
	   nothing; caching httpd's array pointer here (in httpd's GRT) fixes it
	   (issue #113, same class as #111). */
	httpd->credarr = cred_array();

    /* unlock the httpd */
    unlock(httpd,0);

    /* remove ESTAE */
    abendrpt(ESTAE_DELETE, DUMP_DEFAULT);

    http_exit("initialize()\n");
    return initrc;
}

