static void
close_fd_set(void)
{
    CLIBGRT *grt    = __grtget();

    http_enter("close_fd_set()\n");
    if (grt->grtsock) {
        unsigned count  = array_count(&grt->grtsock);
        while(count > 0) {
            count--;
            CLIBSOCK *s = grt->grtsock[count];
            if (!s) continue;
            if (s->socket >= 0) {
                closesocket(s->socket);
            }
        }
    }
    http_exit("close_fd_set()\n");
}

static void
terminate(void)
{
    CLIBGRT *grt        = __grtget();
    HTTPD   *httpd      = grt->grtapp1;
    HTTPC   *httpc;
    int     i;
    unsigned count;
    unsigned n;

    http_enter("terminate()\n");

    httpd->flag |= HTTPD_FLAG_QUIESCE;
    httpd->flag |= HTTPD_FLAG_SHUTDOWN;

    if (httpd->socket_thread) {
        CTHDTASK *task = httpd->socket_thread;

        for(i=0; (i < 10) && (!(task->termecb & 0x40000000)); i++) {
            if (i) {
                wtof(MSG_WAIT_SOCKET_THREAD, i);
            }
            /* we need to wait 1 second */
            __asm__("STIMER WAIT,BINTVL==F'100'   1 seconds");
        }

        if(!(task->termecb & 0x40000000)) {
            wtof(MSG_FORCE_DETACH);
        }
        cthread_delete(&httpd->socket_thread);
    }

    /* close the listener socket */
    if (httpd->listen > 0) {
        http_dbgf("closing socket(%d)\n", httpd->listen);
        closesocket(httpd->listen);
        httpd->listen = 0;
    }

    /* terminate the worker threads */
    cthread_manager_term(&httpd->mgr);

    if (httpd->httpc) {
        for(httpc=httpd->httpc[0]; httpc; httpc=httpd->httpc[0]) {
            http_dbgf("closing socket(%d)\n", httpc->socket);
            http_close(httpc);
        }
        array_free(&httpd->httpc);
    }

    /* cleanup the CGI array */
    if (httpd->route) {
        count = array_count(&httpd->route);

        for(n=0; n < count; n++) {
            HTTPROUTE *route = httpd->route[n];
			if (route->pgm) 	free(route->pgm);
			if (route->path) 	free(route->path); 
            free(route);
        }

        array_free(&httpd->route);
    }

    /* free the per-CGI context pointer array (M11); the blocks it points to
       are AS-lifetime __getm storage by design and are not freed here */
    if (httpd->cgictx) {
        free(httpd->cgictx);
        httpd->cgictx = NULL;
    }

    /* httpd->ufs removed — per-client sessions freed in httpclos.c */

    if (httpd->ufssys) {
        ufs_sys_term(&httpd->ufssys);
        httpd->ufssys = NULL;
    }

	wtof(MSG_STATS,
		httpd->total_requests, httpd->total_errors,
		httpd->total_bytes_sent);

    /* just in case we missed something */
    close_fd_set();

    wtof(MSG_SHUTDOWN_DONE);

    http_exit("terminate()\n");
}

static int
build_fd_set(fd_set *read, fd_set *write, fd_set *excp)
{
    CLIBGRT     *grt    = __grtget();
    HTTPD       *httpd  = grt->grtapp1;
    int         maxsock = 0;
    unsigned    count   = array_count(&httpd->httpc);
    unsigned    n;
    HTTPC       *httpc;
#if 0
    http_enter("build_fd_set()\n");
#endif
    if (read && httpd->listen >= 0) {
        memset(read, 0, sizeof(fd_set));
        FD_SET(httpd->listen, read);
        if (httpd->listen > maxsock) maxsock = httpd->listen;
    }
    if (write) {
        memset(write, 0, sizeof(fd_set));
    }
    if (excp) {
        memset(excp, 0, sizeof(fd_set));
    }

    /* httpd->httpc[] is read here without the lock.  That is safe because the
     * array has exactly one writer, and it is this thread -- not because of
     * any NULL in it (#235).
     *
     * Entries reach it only through the accept path below, in the branch taken
     * when httpd->mgr is NULL -- and that is the no-worker fallback alone, not
     * a startup window.  http_config() is already listening well before this
     * thread exists, but initialize() holds lock(httpd,0) from before
     * cthread_create_ex() until after cthread_manager_init(), and every pass
     * of this loop starts in process_clients() -> http_process_clients(),
     * which ENQs that same resource.  lock() is ENQ RET=HAVE (libc370
     * @@enqdeq.c), so another TCB's holder makes it wait, not fail: this
     * thread cannot reach accept() until mgr is set or has failed.  A
     * connection sitting in the backlog at STC start therefore does not slip
     * into this array, and with a worker pool the array stays empty for the
     * life of the server.
     *
     * Which leaves the fallback -- and no manager means no worker threads at
     * all.  The accept below, both walks over the array, and the array_del()
     * in httpclos() then run on this one thread; nothing else exists to race
     * it.  (Workers, when they exist, take their clients from
     * cthread_queue_add() alone and never see this array.  httpd->busy does
     * hold client pointers a worker touches, but nothing walks it to close or
     * free a client -- it is add / delete-this-one / compare-only.)
     *
     * One exception, worth knowing before trusting this: if the socket thread
     * does not post its termination ECB within 10s, terminate() says
     * HTTPD041I, detaches it anyway, and then walks and frees this array from
     * the main thread.  A socket thread still running past that point is a
     * second writer -- and a far wider problem than this array.
     *
     * What stood here claimed array_del() "sets entries to NULL before removal,
     * and we check for NULL below".  It does not: arraydel() shifts every later
     * element left and NULLs only the slot past the new count (libc370
     * @@ardel.c).  The check that argument justified is gone with the
     * single-writer finding; see docs/development.md, "Dynamic arrays: no holes
     * below the count".
     */
    for(n=0; n < count; n++) {
        httpc = httpd->httpc[n];

        if (httpc->socket < 0) continue;   /* no socket? */

        if (httpc->socket > maxsock) maxsock = httpc->socket;
        if (read)   FD_SET(httpc->socket, read);
        if (write)  FD_SET(httpc->socket, write);
        if (excp)   FD_SET(httpc->socket, excp);
    }

    if (maxsock) maxsock++;
#if 0
    http_exit("build_fd_set(), maxsock=%d\n", maxsock);
#endif
    return maxsock;
}

static int
process_clients(fd_set *read, fd_set *write, fd_set *excp)
{
    CLIBGRT     *grt    = __grtget();
    HTTPD       *httpd  = grt->grtapp1;
    int         rc      = http_process_clients();
    int         lockrc;
    unsigned    count;
    unsigned    n;
    HTTPC       *httpc;

    /* process all the http clients (does its own locking) */
    rc = http_process_clients();

    /* get lock so we can cleanup any clients that are closing */
    lockrc = lock(httpd, 0);
    if (lockrc==0) goto httpd_locked;   /* we have the lock */
    if (lockrc==8) goto httpd_locked;   /* we already had the lock */
    wtof(MSG_LOCK_FAILED, __func__);
    goto quit;

httpd_locked:
    /* look for any clients that need to be closed */
    count = array_count(&httpd->httpc);
    for(n=0; n < count; n++) {
        httpc = httpd->httpc[n];

        if (httpc->state==CSTATE_CLOSE) {
            /* we close a single client at a time,
            ** other clients will be closed on next pass.
            */
            http_dbgf("closing client(%u) socket(%d)\n",
                n+1, httpc->socket);
            http_close(httpc);
            break;
        }
    }
    if (lockrc==0) unlock(httpd, 0);

quit:
    return 0;
}

/* NOTE: an earlier version of this probe bisected with malloc() to report the
   largest obtainable block.  It abended the socket thread S878 on its second
   run -- libc370's malloc goes to @@GETM, which issues GETMAIN **RU**
   (unconditional): under storage pressure it abends instead of returning
   NULL.  That is the defect this debugging found, so the probe must never
   allocate; it only reports counts. */

static int
socket_thread(void *arg1, void *arg2)
{
    CLIBGRT     *grt    = __grtget();
    HTTPD       *httpd  = grt->grtapp1;
    unsigned    *psa    = (unsigned *)0;
    unsigned    *tcb    = (unsigned *)psa[0x21C/4]; /* A(TCB) from PSATOLD  */
    CTHDTASK    *task   = cthread_self();
    CTHDMGR     *mgr    = httpd->mgr;
    int         rc;
    int         sock;
    int         len;
    HTTPC       *httpc;
    timeval     wait;
    int         maxsock;
    unsigned    count;
    fd_set      read;
    struct sockaddr_in addr;
    struct sockaddr_in *a = (struct sockaddr_in *)&addr;
    time64_t    last_sweep = time64(NULL);  /* credential reaper throttle (M2) */

    http_enter("socket_thread()\n");

    wtof(MSG_THREAD_START, "SOCKET THREAD", tcb, task, task->stacksize);

    /* if something goes all wrong, capture it! */
    abendrpt(ESTAE_CREATE, DUMP_DEFAULT);

    /* we loop until we're shut down */
    while(task) {
        if (httpd->flag & HTTPD_FLAG_SHUTDOWN) break;

        /* periodically reap idle credentials (M2), throttled to ~60s so the
           select loop's ~1/s wakeups don't sweep every tick */
        {
            time64_t now = time64(NULL);
            if (difftime64(now, last_sweep) >= 60.0) {
                last_sweep = now;
                if (httpd->cfg_session_timeout || httpd->cfg_session_maxage)
                    cred_reap((unsigned)httpd->cfg_session_timeout * 60,
                              (unsigned)httpd->cfg_session_maxage * 60);
            }
        }

        /* process clients */
        if (process_clients(&read, NULL, NULL)) break;

        /* build fd_set for select() */
        maxsock = build_fd_set(&read, NULL, NULL);
        if (!maxsock) {
            wtof(MSG_MAXSOCK_ZERO);
            goto quit;
        }

        /* set the wait interval */
        wait.tv_sec     = 0;
        wait.tv_usec    = 0;

        mgr = httpd->mgr;
        if (mgr) {
            /* we're using worker threads for client processing */
            wait.tv_sec = 1;

            /* if we're quiesced then break out of loop */
            if (httpd->flag & HTTPD_FLAG_QUIESCE) break;
        }
        else {
            /* we're doing client processing from this thread */
            count       = array_count(&httpd->httpc);

            if (count==0) {
                /* no clients, so wait just a little bit */
                wait.tv_sec = 1;

                /* if we're quiesced then break out of loop */
                if (httpd->flag & HTTPD_FLAG_QUIESCE) break;
            }
        }

        /* wait for something to do */
        rc = selectex(maxsock, &read, NULL, NULL, &wait, NULL);
        if (rc<0) {
            if (httpd->flag & HTTPD_FLAG_QUIESCE) continue;     /* checked at top of loop */
            if (httpd->flag & HTTPD_FLAG_SHUTDOWN) continue;    /* checked at top of loop */
            wtof(MSG_SELECT_FAILED, rc, errno);
            goto quit;
        }

        /* if we're quiesced then don't accept new connections */
        if (httpd->flag & HTTPD_FLAG_QUIESCE) continue;

        /* first check for new connections */
        if (FD_ISSET(httpd->listen, &read)) {
            /* new client wants to connect */
            len = sizeof(addr);
            sock = accept(httpd->listen, &addr, &len);
            if (sock<0) {
                /* transient (client reset before accept, EINTR, ...): drop
                   this connection but keep listening.  A real shutdown/quiesce
                   is handled at the top of the loop, so don't kill the
                   listener on a single accept() failure. */
                if (httpd->flag & HTTPD_FLAG_QUIESCE) continue;
                if (httpd->flag & HTTPD_FLAG_SHUTDOWN) continue;
                wtof(MSG_ACCEPT_FAILED, sock, errno);
                http_dbgf("accept() failed, rc=%d, error=%d\n", sock, errno);
                continue;
            }

            http_dbgf("new connection on socket=%d\n", sock);

            len = 1;    /* set non-blocking I/O */
            if (ioctlsocket(sock, FIONBIO, &len)) {
                wtof(MSG_NONBLOCK_FAILED, sock);
                http_dbgf("Unable to set non-blocking I/O for socket %d\n",
                    sock);
            }

            /* we've accepted a connection */
            httpc = calloc(1, sizeof(HTTPC));
            if (!httpc) {
                /* out of memory for this client: close the accepted socket
                   (don't leak the fd) and keep listening -- memory may free
                   up; a persistent OOM still lets QUIESCE/SHUTDOWN exit. */
                wtof(MSG_OUT_OF_MEMORY);
                closesocket(sock);
                continue;
            }
            strcpy(httpc->eye, HTTPC_EYE);
            httpc->httpd  = httpd;
            httpc->socket = sock;
            httpc->addr   = a->sin_addr.s_addr;
            httpc->port   = a->sin_port;
            httpc->state  = CSTATE_IN;
            httpsecs(&httpc->start);
            httpd->active_connections++;

            // SMF session tracking
            {
                time_t now = time(0);
                struct tm *tm = localtime(&now);
                httpc->connect_time = (unsigned)(
                    tm->tm_hour * 360000L
                    + tm->tm_min * 6000L
                    + tm->tm_sec * 100L);
            }
            /* UFS session created lazily by http_get_ufs() */

            mgr = httpd->mgr;
            if (mgr) {
                /* we have a thread manager */
                if (mgr->state == CTHDMGR_STATE_QUIESCE ||
                    mgr->state == CTHDMGR_STATE_STOPPED) {
                    /* manager is not available */
                    http_close(httpc);
                }
                else {
                    /* queue client to thread manager work queue.  A calloc
                       OOM inside cthread_queue_add returns non-zero without
                       queueing -- close the client so its HTTPC + socket don't
                       leak.  (Success returns 0; a QUIESCE/STOPPED race also
                       returns 0 there, but is covered by the state check above
                       -- the narrow remaining window is benign, reclaimed at
                       address-space end.) */
                    if (cthread_queue_add(mgr, httpc)) {
                        http_close(httpc);
                    }
                }
            }
            else {
                /* add new client to array of clients */
                lock(httpd, 0);
                array_add(&httpd->httpc, httpc);
                unlock(httpd, 0);
            }
        } /* if (FD_ISSET(httpd->listen, &read)) */

    } /* while(task) */

quit:
	wtof(MSG_THREAD_STOP, "SOCKET THREAD", tcb, task, task->stacksize);

    abendrpt(ESTAE_DELETE, DUMP_DEFAULT);
    http_exit("socket_thread()\n");
    return 0;
}

/* Drive one client's state machine to completion (or to shutdown).  Split
   out so worker_thread can run it under try() (ESTAE): a core abend anywhere
   in the request pipeline then returns here for cleanup instead of
   percolating past http_close() -- which would otherwise leak the HTTPC, its
   socket, env and UFS handles and leave a stale pointer in httpd->busy (M1). */
static int
serve_client(HTTPC *httpc, CTHDWORK *work)
{
    /* DEBUG #217: this loop had no escape.  http_process_client() may return
       without advancing httpc->state (the busy-exit in httppc.c), and there is
       no wait anywhere in the loop, so the worker then spins on ENQ/DEQ
       forever and is lost to the pool.  Count passes that change nothing and
       break out, loudly, instead of taking the address space down. */
    int     spin    = 0;
    short   last    = httpc->state;

    while (httpc->state != CSTATE_CLOSE) {
        http_process_client(httpc);
        if (work->state == CTHDWORK_STATE_SHUTDOWN) break;

        if (httpc->state == last) {
            /* No progress.  In worker mode this client has exactly one owner
               -- this loop; it came off the work queue and nothing else
               processes it.  So if the no-progress pass was httppc()'s
               busy-exit, the httpd->busy entry is stale by definition (#159:
               left behind by an earlier failure on this worker, or by a freed
               client that occupied the same storage).  Clear it on the FIRST
               such pass and keep serving: the request proceeds normally and
               the wedge never forms.  If the client is NOT in busy, the stall
               has another cause (e.g. http_set_busy() failing on a full
               region) -- nothing to repair here, let the spin guard below end
               it.  The guard stays as the last resort either way. */
            if (spin == 0 && http_is_busy(httpc)) {
                wtof(MSG_STALE_BUSY,
                    httpc, (int)httpc->state, httpc->socket,
                    httpc->request_count);
                http_reset_busy(httpc);
            }
            if (++spin >= 1000) {
                wtof(MSG_SPIN,
                    httpc, (int)httpc->state, httpc->socket,
                    httpc->request_count, work);
                /* The spin means httppc() kept taking its busy-exit without
                   ever reaching http_reset_busy(), so this client is still in
                   httpd->busy -- and http_close() does not clear that array.
                   Drop the entry here, or the freed HTTPC address stays behind
                   and wedges the next client allocated at it. */
                http_reset_busy(httpc);
                httpc->state = CSTATE_CLOSE;
                break;
            }
        }
        else {
            spin = 0;
            last = httpc->state;
        }
    }
    return 0;
}

static int
worker_thread(void *udata, CTHDWORK *work)
{
    unsigned    *psa    = (unsigned *)0;
    unsigned    *tcb    = (unsigned *)psa[0x21C/4]; /* A(TCB) from PSATOLD  */
    CTHDTASK    *task   = cthread_self();
    int         rc      = 0;
    char        *data   = NULL;
    HTTPC       *httpc  = NULL;
    char        name[20];   /* "WORKER(xxxxxx)" for HTTPD060I/061I */

    http_enter("worker_thread()\n");

    /* if something goes all wrong, capture it! */
    abendrpt(ESTAE_CREATE, DUMP_DEFAULT);

    sprintf(name, "WORKER(%06X)", (unsigned)work);
    wtof(MSG_THREAD_START, name, tcb, task, task->stacksize);

    while(task) {
        if (work->state == CTHDWORK_STATE_SHUTDOWN) break;

        rc = cthread_worker_wait(work,&data);
        if (rc == CTHDWORK_POST_SHUTDOWN) break;

        if (rc == CTHDWORK_POST_REQUEST) {
            /* process request */
            httpc = (HTTPC*)data;
            if (httpc && strcmp(httpc->eye, HTTPC_EYE)==0) {
                /* Run the request under ESTAE.  A core abend (not a CGI under
                   __linkds, whose abends are caught there) would otherwise
                   skip http_close() and leak the client; try() catches it so
                   cleanup still runs.  On an abend the pipeline never reached
                   http_reset_busy() (httppc.c:149), so drop the stale busy
                   entry here -- while httpc is still valid, before close frees
                   it.  The normal path already cleared busy, so gate on rc. */
                rc = try(serve_client, httpc, work);
                if (rc) {
                    wtof(MSG_WORKER_ABEND,
                        rc, work, httpc, httpc->socket);
                    http_reset_busy(httpc);
                }
                http_dbgf("closing client(%08X) socket(%d)\n",
                    httpc, httpc->socket);
                http_close(httpc);
            }
            else {
                wtodumpf(data, 16, "%s unknown request", __func__);
            }
        }
        else if (rc == CTHDWORK_POST_TIMER) {
            /* process timer */
        }
    }

	wtof(MSG_THREAD_STOP, name, tcb, task, task->stacksize);

    abendrpt(ESTAE_DELETE, DUMP_DEFAULT);

    http_exit("worker_thread()\n");
    return 0;
}

static unsigned
build_ecblist(COM *com, unsigned **ecblist)
{
    unsigned        pos     = 0;
    unsigned        *ecbp;

    if (com->comecbpt) {
        ecblist[pos++] = com->comecbpt;
    }

    if (pos) {
        ecbp = ecblist[pos-1];
        ecblist[pos-1] = (unsigned*)((unsigned)ecbp | 0x80000000);
    }

    return pos;
}

#include "cde.h"
static CDE *
find_cde(const char *name)
{
    unsigned    *psa    = 0;                        /* low core == PSA      */
    unsigned    *tcb    = (unsigned*)psa[0x21c/4];  /* TCB      == PSATOLD  */
    unsigned    *jstcb  = (unsigned*)tcb[0x7c/4];   /* JSTCB    == TCBJSTCB */
    CDE         *cde    = (CDE*)jstcb[0x2c/4];      /* CDE      == TCBJPQ   */
    int         i;
    char        temp[9] = "        ";

    for(i=0; i < 8 && name[i]; i++) {
        temp[i] = name[i];
    }

    while(cde) {
        if (memcmp(cde->CDNAME, temp, 8)==0) {
            return cde;
            break;
        }
        cde = cde->CDCHAIN;
    }

    return NULL;
}

static int
auth_cde(CDE *cde)
{
    int     rc = 0;

    if (cde) {
        __asm__("MODESET KEY=ZERO,MODE=SUP\n" : : : "0", "1", "14", "15");
        cde->CDATTR2 |= (CDSYSLIB | CDAUTH);
        __asm__("MODESET KEY=NZERO,MODE=PROB" : : : "0", "1", "14", "15");
    }

    return rc;
}

static int
auth_name(const char *name)
{
    int     rc = 0;
    CDE     *cde = find_cde(name);

    if (cde) {
        /* wtodumpf(cde, sizeof(CDE), "%s %s CDE before auth_cde()", __func__, name); */
        rc = auth_cde(cde);
        /* wtodumpf(cde, sizeof(CDE), "%s %s CDE after auth_cde()", __func__, name); */
    }
    else {
        /* wtof("%s %s CDE was not found", __func__, name); */
        rc = 4;
    }

    return rc;
}

static int
identify_cthread(void)
{
    int     rc = 0;

    /* CTHREAD does not already exist, identify it now */
    /* wtof("%s preparing to IDENTIFY CTHREAD", __func__); */

    __asm__("L     1,=V(CTHREAD)    A(thread driver routine)\n\t"
            "LA    0,=CL8'CTHREAD'\n\t"
            "IDENTIFY EPLOC=(0),ENTRY=(1)\n\t"
            "ST    15,0(,%0)\n" : : "r" (&rc): "0", "1", "14", "15");
    __asm__("\n*\n");

    /* wtof("%s IDENTIFY CTHREAD rc=%d", __func__, rc); */

    rc = auth_name("CTHREAD");

    return rc;
}

static int auth_setup(const char *name)
{
    int     rc = 0;

    return rc;
}

static int unauth_setup(const char *name)
{
    int         rc      = 0;
    CLIBCRT     *crt    = __crtget();   /* A(CLIBCRT)               */

    /* this task is not currently APF authorized */
    rc = __autask();    /* APF authorize this task  */
    /* wtof("%s __autask() rc=%d", __func__, rc); */
    if (rc==0) {
        if (crt->crtauth & CRTAUTH_ON) {
            /* Silent on the healthy path (UFSD/FTPD do the same): that APF was
            ** obtained is only interesting when it FAILS, and HTTPD012E covers
            ** that. */
            /* we want the STEPLIB APF authorized as well */
            rc = __austep();    /* APF authorize the STEPLIB */
            if (rc==0) {
                if (crt->crtauth & CRTAUTH_STEPLIB) {
                    rc = auth_name(name);
                    /* wtof("%s auth_name(%s) rc=%d", __func__, name, rc); */
                    rc = identify_cthread();
                    /* wtof("%s identify_cthread() rc=%d", __func__, rc); */
                }
            }
        }
        else {
            rc = auth_name(name);
            /* wtof("%s auth_name(%s) rc=%d", __func__, name, rc); */
            rc = identify_cthread();
            /* wtof("%s identify_cthread() rc=%d", __func__, rc); */
        }
    }
    else {
        wtof(MSG_APF_FAILED, name);
    }

    return rc;
}

int
main(int argc, char **argv)
{
    CLIBCRT     *crt    = __crtget();   /* A(CLIBCRT)               */
    CLIBGRT     *grt    = __grtget();   /* A(CLIBGRT)               */
    HTTPD       *httpd  = 0;
#if 0
    unsigned    *psa    = (unsigned *)0;
    unsigned    *tcb    = (unsigned *)psa[0x21C/4]; /* A(TCB) from PSATOLD  */
    unsigned    *asxb   = (unsigned *)ascb[0x6C/4]; /* A(ASXB) from ASCBASXB*/
    unsigned    *acee   = (unsigned *)asxb[0xC8/4]; /* A(ACEE) from ASXBSENV*/
#endif
    COM         *com    = __gtcom();
    CIB         *cib;
    int         i;
    int         rc;
    int         apf_at_entry;   /* authorized before auth_setup()? (#197) */
    unsigned    count;
    unsigned    *ecblist[10];
    HTTPD       server;
    char        vers[24];           /* MBT_VERSION, upper case: 000I/001I */

    grt->grtapp1    = &server;
    httpd           = grt->grtapp1;

    /* Zero the block HERE, not in initialize().  `server` is automatic storage
       and starts as whatever was on the stack, and two things read it before
       initialize() runs or without initialize() running at all: stc_identity()
       stores the retained ACEE into it, and the early `goto quit` paths below
       reach stc_identity_restore(), which tests that same field.  With the
       memset still down in initialize() those paths would act on garbage
       (#197). */
    memset(httpd, 0, sizeof(HTTPD));

    /* Which route authorizes the STC decides whether its own module storage is
    ** writable, and the log did not say until #197 sent someone looking.
    **
    ** MEASURE it with TESTAUTH -- do not infer it from crtopts below.
    ** `crtopts` is declared in libc370's clibcrt.h and read in @@apfset.c, but
    ** NOTHING IN LIBC370 EVER ASSIGNS IT: the CRT is zeroed, so CRTOPTS_AUTH
    ** is permanently clear.  A message built on it reports "BY SVC" on a
    ** module that was demonstrably fetched key 0, which is exactly what the
    ** first HTTPD002I said on mvsdev.  __isauth() is one TESTAUTH, no
    ** supervisor state, and it is what UFSD007I / FTPD008I already use.
    **
    ** It has to run BEFORE the setup below: after __autask() every task is
    ** authorized and the distinction is gone. */
    apf_at_entry = __isauth();

    /* Deliberately still on crtopts, dead field and all.  Because it is
    ** permanently clear this always takes unauth_setup(), the path that calls
    ** __autask() AND identify_cthread() -- and CTHREAD must be IDENTIFYed or
    ** `ATTACH EP=CTHREAD` (libc370 @@ctcrtx.c) finds nothing, since CTHREAD is
    ** an ENTRY inside this load module and not a library member.  auth_setup()
    ** is an empty stub, so "correcting" this test to __isauth() would, on a
    ** system that authorizes by library, skip the IDENTIFY and leave the
    ** server unable to create a single thread.  The dead field is what has
    ** been protecting httpd, ufsd and ftpd all along; see libc370#122 before
    ** touching either half. */
    if (crt->crtopts & CRTOPTS_AUTH) {
        /* this task was previously authorized */
        rc = auth_setup(argv[0]);
    }
    else {
        /* this task has not been authorized yet */
        rc = unauth_setup(argv[0]);
    }
    /* Startup banner, AFTER the APF setup above and deliberately so: an
    ** unauthorized WTO is prefixed '+' by the system, and the first two lines
    ** an operator reads should not be decorated with a diagnostic about a
    ** state that is about to change anyway.  It is still before the `rc`
    ** check, so a build that FAILS to authorize is identified in the log too
    ** -- with the '+', which at that point is the truth.
    **
    ** Which HTTPD, built from which source, against which C runtime: a
    ** deploy/relink mismatch (sysroot says X, the STC runs Y) then cannot
    ** hide, and a build carrying uncommitted changes says so instead of
    ** passing itself off as the commit it was branched from.  The buffers are
    ** scoped: they are dead the moment the banner is out. */
    /* Startup banner.  Which HTTPD, built from which source, against which C
    ** runtime.  A deploy/relink mismatch (sysroot says X, the STC runs Y) then
    ** cannot hide, and a build carrying uncommitted changes says so instead of
    ** passing itself off as the commit it was branched from.
    **
    ** If these lines have a leading '+' then we are not APF authorized yet --
    ** which is why the banner comes before auth_setup() and not after.  The
    ** buffers are scoped: they are dead the moment the banner is out. */
    http_upcase(vers, sizeof(vers), MBT_VERSION);
    {
        char commit[24];
        char stamp[48];

        wtof(MSG_STARTING,
             vers, http_upcase(commit, sizeof(commit), MBT_COMMIT));
        wtof(MSG_LIBC_VERSION,
             http_upcase(stamp, sizeof(stamp), libc370_version()));
#if MBT_COMMIT_DIRTY
        wtof(MSG_BUILD_DIRTY);
#endif
        /* The key is inferred from the route, not measured: an authorized job
        ** step has its module fetched key 0, an unauthorized one key 8, and
        ** SVC 244 arrives too late to change either.  It belongs next to the
        ** version banner because it is the other half of "which HTTPD is this"
        ** -- the same load module behaves differently depending on how it got
        ** authorized, and #197 was hard to place precisely because nothing
        ** said which route this STC had taken.
        **
        ** Silent when the setup FAILED: HTTPD012E has already said so, and
        ** naming a route there would claim an authorization the task does not
        ** hold.  FTPD008I suppresses it the same way; UFSD007I does not need
        ** to, because ufsd gives up before its banner. */
        if (!rc) {
            if (apf_at_entry)
                wtof(MSG_APF_BY_LIB);
            else
                wtof(MSG_APF_BY_SVC);
        }
    }

    if (rc) goto quit;

#if 0
    for(i=0;i<argc;i++) {
        wtof("arg#%d=\"%s\"", i, argv[i] ? argv[i] : "(null)");
    }
#endif

#if 0
    wtof("main ASCB(%08X) ASXB(%08X) ASXBSENV(%08X)", ascb, asxb, acee);
    if (acee) {
        wtof("ACEEACEE=%-4.4s", acee);
    }
#endif

    if (!com) {
        wtof(MSG_CONSOLE_FAILED);
        goto quit;
    }

#if 0
    /* If this is ever re-enabled: try() returns the ABEND code, which is not
       the same thing as initialize()'s return value (#226) -- one of them has
       to go somewhere else, or a config refusal and an abend become one
       number again. */
    rc = try(initialize,argc,argv);
    if (rc) {
        /* report abend and exit */
        rc = report_abend((unsigned)rc);
        goto cleanup;
    }
#else
    /* Note: All the heavy lifting occurs in the threads created by initialize().
       rc is the step return code from here on: 0 unless the server refused to
       start, and nothing below writes it, so a normal P HTTPD still ends
       CC 0000 (#226). */
    rc = initialize(argc,argv);
#endif

    if (!httpd->listen) {
        /* no listener socket, exit -- rc says whether that was a refusal */
        goto cleanup;
    }

#if 0
    /* issue "maxrates" command to the hercules console */
    httpcmd("maxrates", buf, sizeof(buf));
    wtof("%s", buf);
#endif

    /* set number of modify commands we'll queue */
    __cibset(5);

    httpd->flag |= HTTPD_FLAG_READY;
    /* The docroot is a UFS path and keeps its case; without one there is
       nothing to serve statically and saying "SERVING" would be a lie. */
    if (httpd->docroot[0])
        wtof(MSG_READY, vers, httpd->docroot);
    else
        wtof(MSG_READY_NODOC, vers);

    /* Note: The main thread (this thread) waits for console messages
     * like modify "/F jobname,..." and stop "/P jobname".
     *
     * The socket_thread() waits for client connections and
     * gives those clients to the thread manager for processing
     * by one of the worker_thread.
     */

    /* wait for a console command and process as needed */
    for(;;) {
        /* check for console command */
        if (*(com->comecbpt) & 0x40000000) {
            cib = __cibget();
            if (cib) {
                /* process console command */
                i = http_console(cib);
                __cibdel(cib);
                if (i) break;	/* must be a stop "/P jobname" */
            }
        }

        memset(ecblist, 0, sizeof(ecblist));
        count = build_ecblist(com, ecblist);
        if (count) {
            __asm__("WAIT ECBLIST=(%0)" : : "r"(ecblist));
        }
        else {
            /* we need to wait 1 second */
            __asm__("STIMER WAIT,BINTVL==F'100'   1 seconds");
        }
    }

cleanup:
    httpd->flag |= HTTPD_FLAG_QUIESCE;
    wtof(MSG_SHUTTING_DOWN);

    i = try(terminate,0);
    if (i) wtof(MSG_TERM_FAILED, i);

quit:
    /* Back to the account that took the authorization out, before giving it
       back -- see stc_identity_restore().  A no-op if the switch never ran, so
       the early-failure paths that reach this label are unaffected. */
    stc_identity_restore(httpd);

    if (crt) {
        if (crt->crtauth & CRTAUTH_STEPLIB) {
            __uastep();    /* reset STEPLIB APF authorization  */
        }
        if (crt->crtauth & CRTAUTH_ON) {
            __uatask();    /* reset APF authorization  */
        }
    }

    return rc;
}

